                        type="number"
                        name="odc_boys_count"
                        value={formData.odc_boys_count}
                        onChange={handleChange}
                        placeholder="Enter ODC boys count"
                        className="w-full border border-gray-300 rounded-md px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
                        min="0"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Cost per Boy (₹)</label>
                      <input
                        type="number"
                        name="odc_cost_per_boy"
                        value={formData.odc_cost_per_boy}
                        onChange={handleChange}
                        placeholder="Enter cost per boy"
                        className="w-full border border-gray-300 rounded-md px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
                        min="0"
                        step="0.01"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Total ODC Boys Cost (₹)</label>
                      <input
                        type="text"
                        value={`₹${displayValues.odcBoysTotal.toLocaleString()}`}
                        readOnly
                        className="w-full border border-gray-300 rounded-md px-3 py-2 bg-gray-100 text-gray-700 font-medium"
                      />
                    </div>
                    <div className="flex items-end">
                      {(formData.odc_boys_count > 0 && formData.odc_cost_per_boy > 0) && (
                        <p className="text-xs text-blue-600">
                          {formData.odc_boys_count} × ₹{parseFloat(formData.odc_cost_per_boy).toLocaleString()} = ₹{displayValues.odcBoysTotal.toLocaleString()}
                        </p>
                      )}
                    </div>
                  </div>
                </div>
              </div>

              {/* Final Payment */}
              <div className="bg-green-100 p-4 rounded-lg border">
                <h4 className="text-md font-medium text-gray-700 mb-3">Final Payment</h4>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-3">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Amount (₹)</label>
                    <input
                      type="number"
                      name="final_amount"
                      value={formData.final_amount}
                      onChange={handleChange}
                      placeholder="Enter final payment amount"
                      className="w-full border border-gray-300 rounded-md px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
                      min="0"
                      step="0.01"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Payment Date</label>
                    <input
                      type="date"
                      name="final_date"
                      value={formData.final_date}
                      onChange={handleChange}
                      className="w-full border border-gray-300 rounded-md px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Receipt Number</label>
                    <input
                      type="text"
                      name="final_receipt"
                      value={formData.final_receipt}
                      onChange={handleChange}
                      placeholder="Enter receipt number"
                      className="w-full border border-gray-300 rounded-md px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
                    />
                  </div>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Payment Method</label>
                  <div className="flex space-x-4">
                    {paymentMethods.map(method => (
                      <label key={method} className="flex items-center">
                        <input
                          type="radio"
                          name="final_method"
                          value={method}
                          checked={formData.final_method === method}
                          onChange={handleChange}
                          className="mr-2"
                        />
                        <span className="text-sm text-gray-700">{method}</span>
                      </label>
                    ))}
                  </div>
                </div>
              </div>
            </div>

            {/* Payment Summary - Enhanced with ODC Boys */}
            <div className="mt-6 bg-white p-4 rounded-lg border-2 border-gray-200">
              <h5 className="text-md font-medium text-gray-800 mb-3">Payment Summary</h5>
              <div className="grid grid-cols-2 md:grid-cols-8 gap-4 text-center">
                <div>
                  <p className="text-sm text-gray-600">Food Total:</p>
                  <p className="text-lg font-bold text-blue-600">₹{(parseFloat(formData.food_total) || 0).toLocaleString()}</p>
                </div>
                <div>
                  <p className="text-sm text-gray-600">Hall Rent:</p>
                  <p className="text-lg font-bold text-purple-600">₹{(parseFloat(formData.hall_rent) || 0).toLocaleString()}</p>
                </div>
                <div>
                  <p className="text-sm text-gray-600">Extra Cost:</p>
                  <p className="text-lg font-bold text-indigo-600">₹{(parseFloat(formData.extra_cost) || 0).toLocaleString()}</p>
                </div>
                <div>
                  <p className="text-sm text-gray-600">ODC Boys:</p>
                  <p className="text-lg font-bold text-cyan-600">₹{displayValues.odcBoysTotal.toLocaleString()}</p>
                </div>
                <div>
                  <p className="text-sm text-gray-600">Total Amount:</p>
                  <p className="text-lg font-bold text-gray-900">₹{(parseFloat(formData.total_amount) || 0).toLocaleString()}</p>
                </div>
                <div>
                  <p className="text-sm text-gray-600">Discount:</p>
                  <p className="text-lg font-bold text-orange-600">₹{(parseFloat(formData.discount) || 0).toLocaleString()}</p>
                </div>
                <div>
                  <p className="text-sm text-gray-600">Total Paid:</p>
                  <p className="text-lg font-bold text-green-600">₹{displayValues.totalPaid.toLocaleString()}</p>
                </div>
                <div>
                  <p className="text-sm text-gray-600">Remaining:</p>
                  <p className="text-lg font-bold text-red-600">₹{displayValues.remaining.toLocaleString()}</p>
                </div>
              </div>
              <div className="mt-3 text-center">
                <p className="text-sm text-gray-600">Status:</p>
                <p className={`text-lg font-bold ${
                  formData.status === 'Fully Paid' ? 'text-green-600' :
                  formData.status === 'Partially Paid' ? 'text-yellow-600' : 'text-red-600'
                }`}>
                  {formData.status}
                </p>
              </div>
            </div>
          </div>

          {/* Notes */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Notes</label>
            <textarea
              name="notes"
              value={formData.notes}
              onChange={handleChange}
              rows={3}
              placeholder="Add any special requirements or notes..."
              className="w-full border border-gray-300 rounded-md px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>

          <div className="flex justify-end space-x-3 pt-4 border-t">
            <button
              type="button"
              onClick={onCancel}
              className="px-6 py-2 text-gray-700 border border-gray-300 rounded-md hover:bg-gray-50"
              disabled={loading}
            >
              Cancel
            </button>
            <button
              type="button"
              onClick={handleSubmit}
              className="px-6 py-2 bg-blue-500 text-white rounded-md hover:bg-blue-600 disabled:opacity-50"
              disabled={loading}
            >
              {loading ? 'Saving...' : (booking ? 'Update Booking' : 'Create Booking')}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default BookingForm;
